import{_ as t,o as i,c as s,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0044 — La vidéo dans la médiathèque : dépôt en flux, requêtes Range, sous-titres et transcription","description":"Extrait de docs/adr/0044-video-depot-en-flux-et-sous-titres.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0044 — La vidéo dans la médiathèque : dépôt en flux, requêtes Range, sous-titres et transcription","description":"Extrait de docs/adr/0044-video-depot-en-flux-et-sous-titres.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0044-video-depot-en-flux-et-sous-titres.md","filePath":"developpeurs/adr/0044-video-depot-en-flux-et-sous-titres.md"}'),n={name:"developpeurs/adr/0044-video-depot-en-flux-et-sous-titres.md"};function a(r,e,d,l,u,c){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0044--la-vidéo-dans-la-médiathèque--dépôt-en-flux-requêtes-range-sous-titres-et-transcription" tabindex="-1">ADR-0044 — La vidéo dans la médiathèque : dépôt en flux, requêtes <code>Range</code>, sous-titres et transcription <a class="header-anchor" href="#adr-0044--la-vidéo-dans-la-médiathèque--dépôt-en-flux-requêtes-range-sous-titres-et-transcription" aria-label="Permalink to &quot;ADR-0044 — La vidéo dans la médiathèque : dépôt en flux, requêtes `Range`, sous-titres et transcription {#adr-0044--la-vidéo-dans-la-médiathèque--dépôt-en-flux-requêtes-range-sous-titres-et-transcription}&quot;">​</a></h1><p><strong>Date :</strong> 23 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §11.1 ; RGAA 4.1, thématique 4 (médias temporels) ; RFC 9110 §14 ; amende les « Négatives » de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a> (dépôt lu en mémoire) et clôt son action « vidéo » ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0038-pieces-jointes-des-formulaires-publics">ADR-0038</a> (antivirus) et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0027-adaptateurs-d-exploitation-livres-inactifs">ADR-0027</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0041 avait écarté la vidéo : un lecteur vidéo demande des morceaux du fichier (<code>Range</code>), et la route de fichier ne savait servir que le tout. Elle notait aussi, parmi ses négatives, que le dépôt lisait le fichier entier en mémoire, dans la limite de <code>MEDIA_UPLOAD_MAX_MB</code> (50 Mo par défaut). Une vidéo de collectivité dépasse vite 100 Mo. La recevoir en mémoire aurait immobilisé autant de mémoire par dépôt en cours.</p><p>Une vidéo publiée engage aussi l&#39;accessibilité. La thématique 4 du RGAA demande une transcription textuelle pour un média temporel, et des sous-titres synchronisés pour une vidéo qui a du son.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. La vidéo entre dans la médiathèque, mp4 et webm seulement.</strong> C&#39;est une famille nouvelle, <code>kind = &quot;video&quot;</code>, sans migration : la colonne n&#39;a pas de contrainte d&#39;énumération.</p><ul><li><strong>Reconnaissance au contenu</strong> (<code>KNOWN_KINDS</code>). Un mp4 se reconnaît à la boîte <code>ftyp</code> et à une marque vidéo, distincte d&#39;un <code>m4a</code>. Un webm se reconnaît à l&#39;en-tête EBML et à un <code>DocType</code> égal à <code>webm</code>.</li><li><strong>Médiathèque seulement</strong> (<code>MEDIA_LIBRARY_ONLY_EXTENSIONS</code>), comme le SVG : jamais en pièce jointe de formulaire public.</li><li><strong>Dimensions</strong> : elles ne sont pas lues (<code>NULL</code>).</li></ul><p><strong>2. Le dépôt de tout média se fait en flux, vers un temporaire promu par renommage</strong> (décision du Product Owner, <code>app/media/upload.py</code>).</p><ul><li><strong>L&#39;analyseur multipart</strong> a désormais un mode en flux, sans dépendance (<code>StreamingFormReader</code>, <code>app/core/multipart.py</code>). Il rend la partie fichier par morceaux de 64 Kio au plus. La longueur annoncée est opposée au plus grand plafond, puis resserrée sur celui de la famille dès l&#39;en-tête de la partie.</li><li><strong>L&#39;ordre des contrôles de l&#39;ADR-0041 est gardé.</strong><ol><li>L&#39;extension, avant de lire un octet.</li><li>Le type réel, sur les premiers 64 Kio (256 Kio pour un SVG), avant toute écriture.</li><li>Au fil de l&#39;eau : le plafond de la famille et les contrôles de tout le fichier.</li><li>Dans le temporaire : le fichier vide, la table des matières d&#39;une archive Office, les dimensions, puis l&#39;antivirus.</li></ol></li><li><strong>Le temporaire</strong> (<code>&lt;MEDIA_ROOT&gt;/.televersements/&lt;uuid&gt;.part</code>) est sur le même système de fichiers que les médias. L&#39;empreinte SHA-256 est calculée au fil de l&#39;eau.</li><li><strong>La promotion</strong> est un <code>os.replace</code> vers la clé définitive, <strong>après le dernier contrôle</strong>, puis la ligne est écrite. Si l&#39;écriture de la ligne échoue, les octets promus sont effacés.</li><li><strong>Tout échec supprime le temporaire</strong> : refus, exception, déconnexion du client, annulation.</li><li><strong>Les temporaires orphelins</strong> (un processus tué) sont effacés par une tâche d&#39;ordonnanceur, <code>media_upload_sweep</code> : globale, horaire, pour les temporaires sans écriture depuis plus d&#39;une heure, 1 000 au plus par passage.</li><li><strong>La mémoire reste bornée</strong>, mesurée sur un dépôt de 6 Mio : environ 65 Kio de tampon, et 128 Kio au plus par écriture.</li></ul><p><strong>3. Un plafond propre à la vidéo</strong> : <code>MEDIA_VIDEO_UPLOAD_MAX_MB</code>, 500 par défaut, entre 1 et 4096. Un réglage illisible refuse le démarrage. Le plafond des autres familles ne change pas.</p><p><strong>4. L&#39;antivirus analyse en flux, et ne laisse jamais passer un fichier qu&#39;il n&#39;a pas analysé.</strong></p><ul><li><code>scan</code> lit le temporaire par morceaux (<code>INSTREAM</code>).</li><li><strong>Les limites de ClamAV 1.4.</strong> Par défaut, il coupe un flux au-delà de 100 Mo (<code>StreamMaxLength</code>), et il rend <code>OK</code> <strong>sans analyser</strong> un fichier au-delà de <code>MaxFileSize</code>. Le service <code>clamav</code> du compose relève donc ces limites par les variables <code>CLAMD_CONF_*</code> : 512 Mo pour le flux et pour le fichier, 1 024 Mo pour l&#39;analyse. Il pose aussi <code>AlertExceedsMax</code>, qui signale tout dépassement au lieu de l&#39;accepter. Si ces variables n&#39;étaient pas prises en compte, le démon couperait à 100 Mo, avant la limite où il accepterait sans analyser : l&#39;échec reste sûr.</li><li><strong>Un dépassement est un refus clair.</strong> <code>INSTREAM size limit exceeded</code> ou <code>Heuristics.Limits.Exceeded</code> donnent un 422 <code>file.too_large</code> (« trop gros pour être analysé »), jamais une acceptation. Cette exception hérite de l&#39;indisponibilité : un appelant qui ne la connaît pas rend un 503.</li><li><strong>Le délai d&#39;analyse</strong> vaut <code>ANTIVIRUS_TIMEOUT_SECONDS</code> par tranche entamée de 100 Mio : 150 s pour 500 Mo avec le réglage par défaut. Une pièce jointe de formulaire garde exactement le délai réglé.</li></ul><p><strong>5. Les routes de fichier servent <code>Range</code>, pour tous les médias</strong> (<code>app/media/serving.py</code>, route publique et aperçu).</p><ul><li>Une plage (<code>bytes=a-b</code>, <code>bytes=a-</code>, <code>bytes=-n</code>) rend <strong>206</strong>, avec <code>Content-Range</code> et <code>Content-Length</code>. Une fin au-delà du fichier est ramenée à son dernier octet.</li><li>Une plage mal écrite ou hors du fichier rend <strong>416</strong>, avec <code>Content-Range: bytes */taille</code>.</li><li><strong>Plusieurs plages : 200 avec le fichier entier.</strong> La RFC 9110 permet d&#39;ignorer <code>Range</code>. Aucun lecteur ne demande un corps <code>multipart/byteranges</code>. Des plages qui se chevauchent sont un moyen connu de faire relire le même fichier au serveur. Et le fichier entier se met en cache.</li><li><strong><code>If-Range</code></strong> qui ne cite pas exactement l&#39;ETag : 200 entier. <strong><code>If-None-Match</code></strong> reste prioritaire (304).</li><li><code>Accept-Ranges: bytes</code> figure sur toute réponse de fichier. Les en-têtes de l&#39;ADR-0041 (ETag, cache immuable, <code>nosniff</code>, CSP du SVG) restent sur les 206.</li><li>Le dépôt d&#39;octets lit à partir du décalage demandé, sans lire ce qui précède.</li></ul><p><strong>6. Sous-titres et transcription (RGAA, thématique 4)</strong> (décision du Product Owner).</p><ul><li><strong>Des sous-titres WebVTT par langue</strong>, dans une nouvelle table <code>media_captions</code> (migration <code>0036</code>), un par couple (média, langue), réservés à la vidéo. <ul><li>Un fichier <code>.vtt</code> est contrôlé à l&#39;écriture : 1 Mio au plus, UTF-8, première ligne <code>WEBVTT</code>, aucun octet nul, et antivirus s&#39;il est branché. Le Core ne lit pas les signaux temporels, c&#39;est le lecteur qui le fait.</li><li>Ses octets sont <strong>immuables</strong>, comme ceux d&#39;un média : remplacer une langue crée un nouvel identifiant, donc une nouvelle adresse, et les nouveaux octets s&#39;écrivent avant l&#39;effacement des anciens.</li><li>Le fichier est servi publiquement (<code>GET /public/media/{id}/captions/{caption_id}</code>) en <code>text/vtt</code>, isolé (<code>CSP: sandbox; default-src &#39;none&#39;</code>, <code>nosniff</code>), avec ETag et cache immuable. Le 404 est le même pour un identifiant inconnu et pour un identifiant d&#39;une autre organisation.</li></ul></li><li><strong>Une transcription textuelle</strong> (<code>transcript</code>), pour le son comme pour la vidéo, traduite comme l&#39;alternative (<code>translations[langue].transcript</code>), et bornée.</li><li><strong><code>is_silent</code></strong> marque une vidéo <strong>sans piste sonore</strong>, sur le modèle d&#39;<code>is_decorative</code>. Une vidéo muette n&#39;a pas besoin de sous-titres. Une vidéo qui ne porte que de la musique n&#39;est pas muette.</li><li><strong><code>missing_captions</code></strong> (une vidéo non muette sans sous-titre) est la liste de travail d&#39;un référent accessibilité (<code>GET /media?missing_captions=true</code>), comme <code>missing_alt</code> pour les images.</li><li><code>MediaOut</code> et <code>PublicMediaOut</code> portent <code>captions</code>, <code>transcript</code> et <code>is_silent</code>, jusque dans l&#39;expansion de <code>/public/resolve</code>. Les sous-titres d&#39;une liste de médias sont chargés en <strong>une</strong> requête.</li></ul><p><strong>7. Le back-office.</strong></p><ul><li><strong>La fiche média</strong> gagne un lecteur vidéo avec ses pistes de sous-titres, la gestion des sous-titres, la case « Vidéo sans piste sonore » et la transcription.</li><li><strong>La liste</strong> gagne la famille vidéo et le filtre « Sous-titres manquants ».</li><li><strong>Le relais BFF</strong> transmet <code>Range</code> à l&#39;aperçu, et fait passer le dépôt en flux jusqu&#39;à l&#39;API.</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Garder le dépôt en mémoire, plafond commun</strong></td><td>Ne conviendrait qu&#39;aux clips courts, et une vidéo occuperait sa taille en mémoire pendant tout le dépôt. Décision du Product Owner.</td></tr><tr><td><strong><code>python-multipart</code>, ou le fichier temporaire d&#39;un <code>UploadFile</code> de Starlette</strong></td><td>Une dépendance de plus, et un contrôle moins fin de l&#39;ordre des contrôles : le type réel doit être vu avant d&#39;écrire la suite. L&#39;analyseur borné du projet se prolonge en flux sans elle.</td></tr><tr><td><strong>Écrire directement à la clé définitive</strong></td><td>Un fichier refusé au dernier contrôle (antivirus) aurait existé un instant là où on le sert. Le renommage atomique ne rend visible qu&#39;un fichier accepté.</td></tr><tr><td><strong>Servir plusieurs plages en <code>multipart/byteranges</code></strong></td><td>Personne ne s&#39;en sert pour lire une vidéo, et des plages qui se chevauchent sont un vecteur d&#39;amplification.</td></tr><tr><td><strong>Reporter les sous-titres dans une action ouverte</strong></td><td>Une vidéo publiée d&#39;ici là n&#39;aurait pas été conforme au RGAA. Décision du Product Owner.</td></tr><tr><td><strong>Sous-titres incrustés, ou pistes du conteneur mp4</strong></td><td>Ils ne se traduisent pas, ne se corrigent pas sans réencoder, et ne s&#39;afficheraient pas partout de la même façon. Un fichier WebVTT par langue est le format de l&#39;élément <code>&lt;track&gt;</code>.</td></tr><tr><td><strong>Transcoder, produire des miniatures ou du streaming adaptatif (HLS, DASH)</strong></td><td>Il faudrait <code>ffmpeg</code>, du temps de calcul et un stockage multiplié. C&#39;est le même refus que pour les miniatures d&#39;images (ADR-0041 §4). Une collectivité qui diffuse beaucoup de vidéo passera par une plateforme dédiée.</td></tr><tr><td><strong>Accepter mov, avi, mkv</strong></td><td>Aucun navigateur ne les lit tous. mp4 (H.264) et webm couvrent la lecture native partout.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Une vidéo se dépose, se lit et s&#39;avance dans le navigateur, depuis le back-office comme depuis un site public.</li><li>La négative de l&#39;ADR-0041 est levée : aucun dépôt, quelle que soit sa famille, ne tient plus le fichier en mémoire.</li><li>Un fichier refusé n&#39;existe jamais à sa place définitive, et un temporaire abandonné finit effacé.</li><li>Une vidéo peut être rendue conforme au RGAA : sous-titres par langue, transcription traduite, liste des vidéos sans sous-titres.</li><li>L&#39;antivirus ne laisse plus passer, faute de l&#39;avoir analysé, un fichier plus gros que ses limites.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Le volume à sauvegarder augmente d&#39;autant</strong> : 500 Mo par vidéo au plafond par défaut. Le répertoire <code>.televersements/</code> sous <code>MEDIA_ROOT</code> peut être exclu des sauvegardes.</li><li><strong>Aucune adaptation de débit.</strong> Une longue vidéo se lit à sa qualité d&#39;origine : un visiteur mal connecté attendra.</li><li><strong>L&#39;ordre des refus change</strong> : un fichier à la fois trop gros et d&#39;un mauvais type reçoit <code>file.content_mismatch</code> plutôt que <code>file.too_large</code>, puisque le type est vu d&#39;abord.</li><li><strong><code>AlertExceedsMax</code> a des effets de bord</strong> : il fait aussi refuser une archive trop profonde (<code>MaxRecursion</code>, <code>MaxFiles</code>), pièce jointe comprise. Une très longue vidéo pourrait dépasser <code>MaxScanTime</code>, non vérifié.</li><li><strong>ClamAV n&#39;a été vérifié que dans ses sources.</strong> La prise en compte des variables <code>CLAMD_CONF_*</code> par l&#39;image l&#39;a été dans ses sources publiques, pas en faisant tourner l&#39;image. Et une fermeture brutale de la connexion par <code>clamd</code>, au-delà de sa limite, peut être lue comme une panne (503) plutôt que comme un refus. Ce chemin n&#39;est pas testé de façon déterministe.</li><li><strong>Pas de dimensions pour une vidéo</strong> : <code>NULL</code>.</li><li><strong>Les transcriptions ne sont pas indexées</strong> dans la recherche du site.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Vidéo mp4 et webm, dépôt en flux, balayage des temporaires, plafond vidéo, antivirus en flux avec refus clair au-delà des limites de <code>clamd</code>, <code>Range</code> sur les routes de fichier — <code>app/media/upload.py</code>, <code>app/core/multipart.py</code>, <code>app/media/serving.py</code>, <code>app/storage/media_files.py</code>, <code>app/antivirus/</code> ; recette <code>apps/api/tests/test_mediatheque_video.py</code>.</li><li>[x] Sous-titres WebVTT et transcription, <code>is_silent</code>, <code>missing_captions</code> (migration <code>0036</code>, <code>app/media/captions.py</code>, <code>app/api/media_captions.py</code>) ; recette <code>apps/api/tests/test_mediatheque_sous_titres.py</code>. Écrans du back-office et relais BFF (<code>Range</code>, dépôt en flux, sous-titres).</li><li>[ ] Éprouver l&#39;antivirus contre le démon ClamAV réel avec une vidéo de plus de 100 Mo, pour confirmer les variables <code>CLAMD_CONF_*</code> de l&#39;image et le refus au-delà de ses limites.</li><li>[ ] Indexer les transcriptions dans la recherche du site, comme le texte des documents (ADR-0043).</li></ul>',28)])])}const g=t(n,[["render",a]]);export{m as __pageData,g as default};
